using FluentValidation;namespace SchoolERP.Application.Features.Houses;
public sealed class CreateHouseRequestValidator:AbstractValidator<CreateHouseRequest>{public CreateHouseRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.ColorHex).NotEmpty().Matches("^#[0-9A-Fa-f]{6}$").WithMessage("House.InvalidColor");RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.Motto).MaximumLength(250);RuleFor(x=>x.Description).MaximumLength(1000);}}
public sealed class UpdateHouseRequestValidator:AbstractValidator<UpdateHouseRequest>{public UpdateHouseRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.ColorHex).NotEmpty().Matches("^#[0-9A-Fa-f]{6}$").WithMessage("House.InvalidColor");RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.Motto).MaximumLength(250);RuleFor(x=>x.Description).MaximumLength(1000);}}
public sealed class ChangeHouseCodeRequestValidator:AbstractValidator<ChangeHouseCodeRequest>{public ChangeHouseCodeRequestValidator()=>RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");}
